    "\u{1F469}\u{1F3FC}\u200D\u{1F9BC}\u200D\u27A1\uFE0F": "\u0633\u064A\u062F\u0629 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u0645\u062A\u062D\u0631\u0643 \u0643\u0647\u0631\u0628\u0627\u0626\u064A: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D \u0648\u0645\u0639\u062A\u062F\u0644 \u0648\u0645\u062A\u062C\u0647 \u0644\u0644\u064A\u0645\u064A\u0646",
    "\u{1F469}\u{1F3FD}\u200D\u{1F9BC}\u200D\u27A1\uFE0F": "\u0633\u064A\u062F\u0629 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u0645\u062A\u062D\u0631\u0643 \u0643\u0647\u0631\u0628\u0627\u0626\u064A: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0645\u0639\u062A\u062F\u0644 \u0648\u0645\u062A\u062C\u0647 \u0644\u0644\u064A\u0645\u064A\u0646",
    "\u{1F469}\u{1F3FE}\u200D\u{1F9BC}\u200D\u27A1\uFE0F": "\u0633\u064A\u062F\u0629 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u0645\u062A\u062D\u0631\u0643 \u0643\u0647\u0631\u0628\u0627\u0626\u064A: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0645\u0639\u062A\u062F\u0644 \u0645\u0627\u0626\u0644 \u0644\u0644\u063A\u0627\u0645\u0642 \u0648\u0645\u062A\u062C\u0647 \u0644\u0644\u064A\u0645\u064A\u0646",
