    "\u{1F9D1}\u{1F3FB}\u200D\u{1F9BD}": "\u0634\u062E\u0635 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u0645\u062A\u062D\u0631\u0643 \u064A\u062F\u0648\u064A: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D",
    "\u{1F9D1}\u{1F3FC}\u200D\u{1F9BD}": "\u0634\u062E\u0635 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u0645\u062A\u062D\u0631\u0643 \u064A\u062F\u0648\u064A: \u0628\u0634\u0631\u0629 \u0628\u0644\u0648\u0646 \u0641\u0627\u062A\u062D \u0648\u0645\u0639\u062A\u062F\u0644",
